async fn show(State(orders): State<Orders>, Path(id): Path<i64>)
    -> Result<Html<String>, StatusCode> {
    let order = orders.find(id).await.map_err(|_| StatusCode::NOT_FOUND)?;   // worker
    let page = OrderTemplate { order }
        .render()
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(Html(page))                                       // render step
}
let app = Router::new().route("/orders/{id}", get(show)).with_state(orders);
